svg(27,'y=arccos(cos x-1)',None,(-1.57,1.57),(1.4,3.2),[('initial branch',sampled(lambda x:math.acos(math.cos(x)-1),-1.57,1.57))])
def inverseG(q,positive):
 if q<=-1 or (not positive and q>=0):return math.nan
 lo,hi=(0,10) if positive else (-40,0)
 for _ in range(70):
  mid=(lo+hi)/2;v=(mid-1)*math.exp(mid)
  if (v<q)==positive:lo=mid
  else:hi=mid
 return (lo+hi)/2
svg(28,'Implicit branches: (y-1)exp(y)=(1+x^2)^(3/2)/3+C',None,(-2,2),(-5,3),[(f'C={c}, '+('positive' if pos else 'negative'),sampled(lambda x:inverseG((1+x*x)**1.5/3+c,pos),-2,2)) for c,pos in [(-1.2,True),(-1.2,False),(-.7,True),(-.7,False),(1,True)]])
svg(29,'y prime = y^2',lambda x,y:y*y,(-3,3),(-4,4),[('y=0',sampled(lambda x:0,-3,3))]+[(f'C={c}',sampled(lambda x:1/(c-x) if abs(c-x)>.015 else math.nan,-3,3)) for c in [-2,0,2]])
svg(30,'y prime = xy',lambda x,y:x*y,(-2,2),(-5,5),[(f'C={c}',sampled(lambda x:c*math.exp(x*x/2),-2,2)) for c in [-1,-.5,0,.5,1]])
def param(f,g,a=0,b=2*math.pi):return [(f(a+(b-a)*i/600),g(a+(b-a)*i/600)) for i in range(601)]
svg(31,'Ellipses and orthogonal parabolas',None,(-3,3),(-3,3),[(f'ellipse k={k}',param(lambda t:k*math.cos(t),lambda t:k/math.sqrt(2)*math.sin(t))) for k in [1,2]]+[(f'y={c}x^2',sampled(lambda x:c*x*x,-3,3)) for c in [-1,-.4,.4,1]])
svg(32,'Cubic families and orthogonal ellipses',None,(-3,3),(-3,3),[(f'k={k}, sign={sg}',sampled(lambda x:sg*math.sqrt(k*x**3) if k*x**3>=0 else math.nan,-3,3)) for k,sg in [(1,1),(1,-1),(-1,1),(-1,-1)]]+[(f'ellipse C={c}',param(lambda t:math.sqrt(c/2)*math.cos(t),lambda t:math.sqrt(c/3)*math.sin(t))) for c in [2,8]])
svg(33,'Hyperbolas and orthogonal hyperbolas',None,(-3,3),(-3,3),[(f'xy={k}',sampled(lambda x:k/x if abs(x)>.025 else math.nan,-3,3)) for k in [-1,1]]+[(f'y^2-x^2={c}, sign={sg}',sampled(lambda x:sg*math.sqrt(x*x+c) if x*x+c>=0 else math.nan,-3,3)) for c,sg in [(1,1),(1,-1),(-1,1),(-1,-1)]])
svg(34,'Reciprocals and orthogonal cubic curves',None,(-3,3),(-3,3),[(f'k={k}',sampled(lambda x:1/(x+k) if abs(x+k)>.025 else math.nan,-3,3)) for k in [-1,0,1]]+[(f'y^3=3x+{c}',sampled(lambda x:math.copysign(abs(3*x+c)**(1/3),3*x+c),-3,3)) for c in [-2,0,2]])
